#include <stdio.h>
#include <stdarg.h>

void report(const char *fmt, ...) {
    va_list list;
    va_start(list, fmt);
    vprintf(fmt, list);
    va_end(list);
    printf("\n");
}

int main(void) {
    report("%d 只猫，一共 %d 条鱼", 3, 9);
    report("只印一句话");
    return 0;
}
